/* AIVIC_FUNCTION_BUNDLE_START owner=sendUnreportedReminderNotification exports=sendUnreportedReminderNotification */
const __aivicBundle_108_sendUnreportedReminderNotification = (() => {
  async function sendUnreportedReminderNotification(input: {
    morning_assembly_start_time?: Date;
    current_time?: Date;
    manager_id?: string;
    manager_email?: string;
    reported_members?: Array<{
      member_id?: string;
      member_name?: string;
      email?: string;
      report_sent_at?: Date;
    }>;
    unreported_members?: Array<{
      member_id?: string;
      member_name?: string;
      email?: string;
    }>;
    all_members?: Array<{
      member_id?: string;
      member_name?: string;
      email?: string;
      report_sent_at?: Date;
    }>;
    missingMembers?: Array<{
      memberId: string;
      memberName: string;
      email: string;
    }>;
    managerEmail?: string;
    scheduledMeetingTime?: Date;
    reportDeadlineMinutes?: number;
  }): Promise<{
    success?: boolean;
    unreported_count?: number;
    notified_at?: Date;
    notificationsSent?: number;
    failedRecipients?: string[];
    sentAt?: Date;
  }> {
    const unreportedList = input.unreported_members ?? input.missingMembers ?? [];
    const currentTime = input.current_time ?? input.scheduledMeetingTime ?? new Date();
    const managerEmailAddr = input.manager_email ?? input.managerEmail ?? "";
    const meetingTime = input.morning_assembly_start_time ?? input.scheduledMeetingTime ?? new Date();
  
    const unreportedCount = unreportedList.length;
  
    if (unreportedCount === 0) {
      return {
        success: true,
        unreported_count: 0,
        notified_at: currentTime,
        notificationsSent: 0,
        failedRecipients: [],
        sentAt: currentTime,
      };
    }
  
    const unreportedNames = unreportedList
      .map((member: any) => member.member_name ?? member.memberName ?? "")
      .filter((name: string) => name.length > 0)
      .join("、");
  
    const minutesUntilMeeting = Math.round(
      (meetingTime.getTime() - currentTime.getTime()) / (1000 * 60)
    );
  
    const subject = `朝会開始${minutesUntilMeeting}分前の催促通知`;
    const body = `報告未提出者: ${unreportedNames}（${unreportedCount}名）\n朝会開始までに報告をお願いします`;
  
    const requestPayload = {
      recipient_email: managerEmailAddr,
      subject: subject,
      body: body,
    };
  
    try {
      const response = await fetch("/api/send-notification", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(requestPayload),
      });
  
      if (!response.ok) {
        return {
          success: false,
          unreported_count: unreportedCount,
          notified_at: currentTime,
          notificationsSent: 0,
          failedRecipients: [managerEmailAddr],
          sentAt: currentTime,
        };
      }
  
      return {
        success: true,
        unreported_count: unreportedCount,
        notified_at: currentTime,
        notificationsSent: 1,
        failedRecipients: [],
        sentAt: currentTime,
      };
    } catch {
      return {
        success: false,
        unreported_count: unreportedCount,
        notified_at: currentTime,
        notificationsSent: 0,
        failedRecipients: [managerEmailAddr],
        sentAt: currentTime,
      };
    }
  }
  return { sendUnreportedReminderNotification };
})();
